import re
from typing import List

# Regex pattern for SemVer 2.0.0
# Matches: optional 'v', major.minor.patch, optional pre-release, optional build metadata
SEMVER_PATTERN = re.compile(
    r'^v?(?P<major>0|[1-9]\d*)\.(?P<minor>0|[1-9]\d*)\.(?P<patch>0|[1-9]\d*)'
    r'(?:-(?P<prerelease>(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?'
    r'(?:\+(?P<build>[0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$'
)


def _parse_identifier(identifier: str):
    """Parse a pre-release identifier into a comparable tuple.
    Returns (is_numeric, value) where is_numeric is True for numeric identifiers."""
    if identifier.isdigit():
        return (True, int(identifier))
    return (False, identifier)


def _parse_version(version: str):
    """Parse a version string and return comparable components."""
    match = SEMVER_PATTERN.fullmatch(version.strip())
    if not match:
        raise ValueError(f"Invalid version: {version}")

    major = int(match.group('major'))
    minor = int(match.group('minor'))
    patch = int(match.group('patch'))

    prerelease_str = match.group('prerelease')
    if prerelease_str is None:
        prerelease = None
    else:
        prerelease = [_parse_identifier(part) for part in prerelease_str.split('.')]

    return (major, minor, patch, prerelease)


def compare(a: str, b: str) -> int:
    """Compare two SemVer version strings.
    Returns -1 if a < b, 0 if equal precedence, 1 if a > b."""
    a_parts = _parse_version(a)
    b_parts = _parse_version(b)

    # Compare major, minor, patch
    for a_val, b_val in zip(a_parts[:3], b_parts[:3]):
        if a_val < b_val:
            return -1
        if a_val > b_val:
            return 1

    # Compare pre-release
    a_pre = a_parts[3]
    b_pre = b_parts[3]

    if a_pre is None and b_pre is None:
        return 0
    if a_pre is None:
        return 1  # Release version has higher precedence than pre-release
    if b_pre is None:
        return -1

    # Compare pre-release identifiers
    for a_id, b_id in zip(a_pre, b_pre):
        a_is_num, a_val = a_id
        b_is_num, b_val = b_id

        if a_is_num and b_is_num:
            if a_val < b_val:
                return -1
            if a_val > b_val:
                return 1
        elif a_is_num and not b_is_num:
            return -1  # Numeric identifiers have lower precedence
        elif not a_is_num and b_is_num:
            return 1
        else:
            # Both alphanumeric - ASCII sort
            if a_val < b_val:
                return -1
            if a_val > b_val:
                return 1

    # If all compared identifiers are equal, the one with fewer identifiers has lower precedence
    if len(a_pre) < len(b_pre):
        return -1
    if len(a_pre) > len(b_pre):
        return 1

    return 0


def sort_versions(versions: List[str]) -> List[str]:
    """Sort version strings by precedence (ascending).
    Stable sort preserves original order for equal precedence."""
    # Use enumerate to maintain stable sort for equal versions
    indexed = list(enumerate(versions))
    indexed.sort(key=lambda x: (_parse_version(x[1]), x[0]))
    return [v for _, v in indexed]

